# view as: answered as the chosen person, read-only
V(){ $P -c "set role authenticated; set request.jwt.claims='{\"sub\":\"00000000-0000-0000-0000-00000000000$1\",\"role\":\"authenticated\"}'; set request.jwt.claim.sub='00000000-0000-0000-0000-00000000000$1'; set request.path='$3'; select public.portal_pre_request(); $2" 2>&1 | tr '\n' ' ' | sed 's/ *$//'; }
tv(){ got="$(V "$2" "$3" "${5:-/classes}")"; if [[ "$got" == $4 ]]; then pass=$((pass+1)); else fail=$((fail+1)); echo "FAIL [$1] got: $got | want: $4"; fi; }
tv "no view-as: board sees all classes" a "select count(*) from classes" "*3"
