t "board cannot view as an admin" a "select view_as_start('00000000-0000-0000-0000-000000000001')" "*active volunteer, centre lead or partner*"
t "volunteer gets no list of people" 4 "select count(*) from view_as_choices()" "0"
t "board gets a list without admins or board" a "select bool_and(role in ('volunteer','centre_lead','partner')) and count(*) > 0 from view_as_choices()" "t"
t "board starts viewing as vol1" a "select view_as_start('00000000-0000-0000-0000-000000000004'); select 1" "*1"
tsu "the use is logged" "select count(*) from view_as_log" "1"
tv "then sees only vol1's class" a "select string_agg(name,',' order by name) from classes" "*A"
tv "and is vol1 to every rule" a "select auth.uid()" "*00000000-0000-0000-0000-000000000004"
tv "status knows who is really looking" a "select view_as_status() ->> 'target'" "*00000000-0000-0000-0000-000000000004"
tv "cannot write while viewing" a "insert into sessions(class_id,session_date) values ('00000000-0000-0000-0000-0000000000a1',current_date+9)" "*read-only transaction*"
tv "cannot write through a function either" a "select log_time_off('Other', current_date, current_date, 'x')" "*read-only transaction*"
tv "other people are not affected" 2 "select string_agg(name,',' order by name) from classes" "*A,B"
